#include "hip_api.h"
using namespace hip_probe;
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("gold MODULE OUT");std::vector<unsigned char>in(16*1024),v(in.size());for(unsigned r=0;r<16;r++)for(unsigned c=0;c<1024;c++)in[r*1024+c]=static_cast<unsigned char>(r*16+c%16+(c/16)*97);Api a(7);a.Check(a.hipInit(0),"init");a.Check(a.hipSetDevice(0),"device");Handle m{},q{},fn{};void *di{},*out{};a.Check(a.LoadModule(&m,argv[1]),"module");a.Check(a.hipStreamCreate(&q),"stream");a.Check(a.hipModuleGetFunction(&fn,m,"qkv_store_byte_gold"),"function");a.Check(a.hipMalloc(&di,in.size()),"input");a.Check(a.hipMalloc(&out,in.size()),"output");a.Check(a.hipMemcpy(di,in.data(),in.size(),1),"upload");a.Check(a.hipMemsetAsync(out,0xa5,in.size(),q),"sentinel");void*args[]={&di,&out};a.Check(a.hipModuleLaunchKernel(fn,1,1,1,32,1,1,0,q,args,nullptr),"fullwave");a.Check(a.hipStreamSynchronize(q),"completion");a.Check(a.hipMemcpy(v.data(),out,v.size(),2),"readback");std::ofstream(argv[2],std::ios::binary).write((char*)v.data(),v.size());size_t diff=0,guard=0;for(unsigned r=0;r<16;r++)for(unsigned c=0;c<1024;c++){if(c>=224&&c<256)diff+=v[r*1024+c]!=in[r*1024+c];else guard+=v[r*1024+c]!=0xa5;}printf("BUTTERFLY_BYTE_GOLD cells=512 fullwave32=1 stride1024=1 each16x16unique256bytes=1 byte_diff=%zu guard_diff=%zu\n",diff,guard);a.hipFree(out);a.hipFree(di);a.hipStreamDestroy(q);a.hipModuleUnload(m);if(diff||guard)throw std::runtime_error("byte route invalid");return 0;}catch(const std::exception&e){fprintf(stderr,"BYTE_GOLD_FAIL %s\n",e.what());return 1;}}
